// UX Guidelines — shared runtime (hamburger menu, arrow-key page navigation)

// Page scroll container: the document itself does not scroll, so the
// scrollbar starts below the topnav instead of covering it.
(() => {
  const nav = document.querySelector('.topnav');
  if (!nav) return;
  const scroller = document.createElement('div');
  scroller.className = 'page-scroll';
  scroller.tabIndex = -1;
  const keep = new Set([nav]);
  document.querySelectorAll('.menu-overlay, .menu-panel').forEach(el => keep.add(el));
  const kids = [...document.body.children].filter(el => !keep.has(el) && el.tagName !== 'SCRIPT');
  const anchor = document.getElementById('menu-panel') || nav;
  anchor.after(scroller);
  kids.forEach(el => scroller.appendChild(el));
  document.documentElement.classList.add('has-scroller');
  window.uxScroller = scroller;
  scroller.focus({ preventScroll: true });
})();

// Arrow keys step through the reference pages in hamburger-menu order.
// The order is read from UX_MENU_TYPES so it cannot drift from the menu itself,
// and the current page comes from the file name rather than data-page: the two
// differ on most pages (power-law-of-practice.html is data-page="power-law"),
// which used to leave the arrows dead everywhere they disagreed.
(() => {
  const order = () => ['index'].concat((window.UX_MENU_TYPES || []).flatMap(g => g.slugs));
  const currentSlug = () => {
    let en = (location.pathname.split('/').pop() || 'index.html').replace(/\.html$/, '') || 'index';
    const here = location.pathname.match(/^\/(fr|de|es|ja|zh)(?:\/|$)/);
    // /fr with no trailing slash leaves the language code as the last segment,
    // which would resolve to a page called "fr". That path is the home page.
    if (here && en === here[1]) en = 'index';
    if (here) {   // on a language path: map the localized slug back to English
      const M = (window.UX_SLUGS && window.UX_SLUGS[here[1]]) || {};
      for (const k in M) { if (M[k] === en) { en = k; break; } }
    }
    return en;
  };
  // Never steal the arrow keys from an open panel, sheet or menu.
  const busy = () => !!document.querySelector(
    '.menu-panel.open, .search-sheet.open, .settings-sheet.open, .bm-sheet.open, .share-menu.open');
  document.addEventListener('keydown', e => {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return;
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) return;
    if (busy()) return;
    const P = order(), i = P.indexOf(currentSlug());
    if (i === -1) return;
    const slug = P[(i + (e.key === 'ArrowRight' ? 1 : -1) + P.length) % P.length];
    const href = slug === 'index' ? 'index.html' : slug + '.html';
    e.preventDefault();
    location.href = window.uxLocalHref ? window.uxLocalHref(href) : href;
  });
})();

(() => {
  const hamburger = document.querySelector('.hamburger');
  const overlay = document.getElementById('menu-overlay');
  const MENU_TYPES = window.UX_MENU_TYPES = [{"label": "Every Page", "slugs": ["chestertons-fence", "conways-law", "galls-law", "hofstadters-law", "nielsens-heuristics", "normans-principles", "power-law-of-practice", "rams-principles", "shneiderman-eight-golden-rules", "tognazzinis-first-principles", "wcag-pour"]}, {"label": "Chat", "slugs": ["automation-bias", "doherty-threshold", "human-in-the-loop", "out-of-the-loop-problem", "postels-law", "teslers-law", "uncanny-valley"]}, {"label": "Dashboards", "slugs": ["data-visualization", "goodharts-law", "yerkes-dodson-law"]}, {"label": "Detail Pages", "slugs": ["canons-of-page-construction", "gestalt-principles", "progressive-disclosure", "weber-fechner-law"]}, {"label": "Flows", "slugs": ["fogg-behavior-model", "hook-model", "ikea-effect", "paradox-of-choice", "peak-end-rule", "zeigarnik-effect"]}, {"label": "Forms", "slugs": ["cognitive-load-theory", "curse-of-knowledge", "millers-law", "stroop-effect"]}, {"label": "Landing Pages", "slugs": ["aesthetic-usability-effect", "contour-bias", "eye-scanning-patterns", "golden-ratio", "gutenberg-principle", "jakobs-law", "rule-of-odds", "rule-of-thirds", "von-restorff-effect"]}, {"label": "Navigation", "slugs": ["fitts-law", "hicks-law", "navigation-patterns", "steering-law", "universal-icons", "zipfs-law"]}, {"label": "Tables", "slugs": ["grid-and-hierarchy", "pareto-principle", "serial-position-effect"]}];
  const panel = document.getElementById('menu-panel');
  const closeBtn = document.querySelector('.menu-close');
  if (!hamburger || !overlay || !panel || !closeBtn) return;
  const open = () => {
    const nav = document.querySelector('.topnav');
    const h = nav ? Math.round(nav.getBoundingClientRect().bottom) : 0;
    panel.style.top = h + 'px';
    overlay.style.top = h + 'px';
    panel.classList.add('open');
    overlay.classList.add('open');
    hamburger.setAttribute('aria-expanded', 'true');
    panel.setAttribute('aria-hidden', 'false');
  };
  const close = () => {
    panel.classList.remove('open');
    overlay.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
    panel.setAttribute('aria-hidden', 'true');
  };
  // Full-page menu: group loose links under "Site" and expand every category
  const links = panel.querySelector('.menu-links');
  if (links) {
    const loose = Array.from(links.children).filter(el => el.classList.contains('menu-link'));
    if (loose.length) {
      const site = document.createElement('details');
      site.className = 'menu-group';
      site.open = true;
      const sum = document.createElement('summary');
      sum.className = 'menu-group-label';
      const sumH = document.createElement('h3');
      sumH.textContent = 'Site';
      sum.appendChild(sumH);
      site.appendChild(sum);
      loose.forEach(el => site.appendChild(el));
      links.appendChild(site);
    }
    // Two ways to browse: by page type (home's order) and by task.
    const siteGroup = links.querySelector('.menu-group:last-of-type');
    const taskWrap = document.createElement('div');
    taskWrap.className = 'menu-groups';
    links.querySelectorAll('.menu-group').forEach(g => taskWrap.appendChild(g));
    const typeWrap = document.createElement('div');
    typeWrap.className = 'menu-groups';
    typeWrap.hidden = true;
    const titleOf = {};
    taskWrap.querySelectorAll('.menu-link').forEach(a => { titleOf[a.getAttribute('href')] = a.textContent; });
    MENU_TYPES.forEach(g => {
      const d = document.createElement('details');
      d.className = 'menu-group';
      d.open = true;
      const sum = document.createElement('summary');
      sum.className = 'menu-group-label';
      const h = document.createElement('h3');
      h.textContent = g.label;
      sum.appendChild(h);
      d.appendChild(sum);
      g.slugs.forEach(slug => {
        const href = slug + '.html';
        const a = document.createElement('a');
        a.className = 'menu-link';
        a.href = href;
        a.textContent = titleOf[href] || slug;
        if (href === (document.documentElement.getAttribute('data-page') || 'index') + '.html') a.classList.add('active');
        d.appendChild(a);
      });
      typeWrap.appendChild(d);
    });
    if (siteGroup) typeWrap.appendChild(siteGroup.cloneNode(true));
    const tabs = document.createElement('div');
    tabs.className = 'menu-views';
    [['type', 'Page Type'], ['task', 'Task Type']].forEach(([v, name]) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'menu-view-tab view-tab';
      b.dataset.view = v;
      b.textContent = name;
      tabs.appendChild(b);
    });
    links.appendChild(tabs);
    links.appendChild(typeWrap);
    links.appendChild(taskWrap);
    const setMenuView = v => {
      const byType = v === 'type';
      typeWrap.hidden = !byType;
      taskWrap.hidden = byType;
      tabs.querySelectorAll('.menu-view-tab').forEach(b => {
        const on = b.dataset.view === v;
        b.classList.toggle('active', on);
        b.setAttribute('aria-pressed', String(on));
      });
      try { localStorage.setItem('ux-home-view', v); } catch (e) {}
    };
    let startView = 'type';
    try { startView = localStorage.getItem('ux-home-view') === 'task' ? 'task' : 'type'; } catch (e) {}
    setMenuView(startView);
    tabs.addEventListener('click', e => {
      const b = e.target.closest('.menu-view-tab');
      if (b) setMenuView(b.dataset.view);
    });
    const mq = window.matchMedia('(max-width: 600px)');
    const syncGroups = () => links.querySelectorAll('.menu-group').forEach(d => { d.open = !mq.matches; });
    syncGroups();
    mq.addEventListener('change', syncGroups);
  }
  // Menu glyph swaps to an X while open (Lucide menu / x), as on ux-icons.com
  const menuSvg = hamburger.querySelector('svg');
  if (menuSvg && !hamburger.querySelector('.ico-close')) {
    menuSvg.classList.add('ico-menu');
    const closeSvg = menuSvg.cloneNode(false);
    closeSvg.setAttribute('class', 'ico-close');
    closeSvg.innerHTML = '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>';
    hamburger.appendChild(closeSvg);
  }
  const syncMenuLabel = () => hamburger.setAttribute('aria-label', panel.classList.contains('open') ? 'Close menu' : 'Open menu');
  hamburger.addEventListener('click', () => { panel.classList.contains('open') ? close() : open(); syncMenuLabel(); });
  new MutationObserver(syncMenuLabel).observe(panel, { attributes: true, attributeFilter: ['class'] });
  closeBtn.addEventListener('click', close);
  overlay.addEventListener('click', close);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
})();


// Settings sheet: theme, language, font size — staged, applied on Save
(() => {
  const topnav = document.querySelector('.topnav');
  if (!topnav) return;
  const THEMES = [['light','Light'],['dark','Dark'],['beige','Beige'],['blue','Blue']];
  const LANGS = [['en','English'],['es','Espa\u00f1ol'],['de','Deutsch'],['fr','Fran\u00e7ais'],['zh','\u4e2d\u6587'],['ja','\u65e5\u672c\u8a9e']];
  const cur = () => ({
    theme: localStorage.getItem('ux-theme') || 'light',
    lang: localStorage.getItem('ux-lang') || 'en',
    font: parseInt(localStorage.getItem('ux-font') || '100', 10)
  });
  // apply saved font scale on load
  const applyFont = pct => { document.documentElement.style.fontSize = pct === 100 ? '' : (pct + '%'); };
  applyFont(cur().font);

  const wrap = document.createElement('div');
  wrap.className = 'settings-wrap';
  const btn = document.createElement('button');
  btn.className = 'settings-btn';
  btn.setAttribute('aria-label', 'Settings');
  btn.setAttribute('aria-haspopup', 'dialog');
  btn.setAttribute('aria-expanded', 'false');
  btn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg"><path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/><circle cx="12" cy="12" r="3"/></svg>';
  wrap.appendChild(btn);
  topnav.appendChild(wrap);

  const sheet = document.createElement('div');
  sheet.className = 'settings-sheet';
  sheet.setAttribute('role', 'dialog');
  sheet.setAttribute('aria-label', 'Settings');
  document.body.appendChild(sheet);

  let staged = cur();
  const T = k => (window.uxT && window.uxT(k)) || k;

  const render = () => {
    sheet.innerHTML = '';
    const head = document.createElement('div');
    head.className = 'sheet-head';
    const title = document.createElement('h2');
    title.className = 'sheet-title';
    title.textContent = T('Settings');
    const x = document.createElement('button');
    x.className = 'sheet-close';
    x.setAttribute('aria-label', T('Close settings'));
    x.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>';
    x.addEventListener('click', close);
    head.appendChild(title);
    head.appendChild(x);
    sheet.appendChild(head);

    const body = document.createElement('div');
    body.className = 'sheet-body';
    const section = (label, items, key) => {
      const sec = document.createElement('div');
      sec.className = 'sheet-section';
      const h = document.createElement('h3');
      h.className = 'sheet-label';
      h.textContent = T(label);
      sec.appendChild(h);
      items.forEach(([code, name]) => {
        const b = document.createElement('button');
        b.className = 'sheet-opt' + (staged[key] === code ? ' active' : '');
        b.setAttribute('role', 'radio');
        b.setAttribute('aria-checked', String(staged[key] === code));
        b.dataset.code = code;
        b.textContent = key === 'theme' ? T(name) : name;
        b.addEventListener('click', () => {
          staged[key] = code;
          render();
        });
        sec.appendChild(b);
      });
      // On phones the same choice is a dropdown, the two sitting side by side
      const sel = document.createElement('select');
      sel.className = 'sheet-select';
      sel.setAttribute('aria-label', T(label));
      items.forEach(([code, name]) => {
        const o = document.createElement('option');
        o.value = code;
        o.textContent = key === 'theme' ? T(name) : name;
        o.selected = staged[key] === code;
        sel.appendChild(o);
      });
      sel.addEventListener('change', () => {
        staged[key] = sel.value;
        sec.querySelectorAll('.sheet-opt').forEach(b => {
          const on = b.dataset.code === sel.value;
          b.classList.toggle('active', on);
          b.setAttribute('aria-checked', String(on));
        });
      });
      sec.appendChild(sel);
      body.appendChild(sec);
    };
    section('Theme', THEMES, 'theme');
    section('Language', LANGS, 'lang');

    const fsec = document.createElement('div');
    fsec.className = 'sheet-section sheet-font-section';
    const fh = document.createElement('h3');
    fh.className = 'sheet-label';
    fh.textContent = T('Font Size');
    fsec.appendChild(fh);
    const frow = document.createElement('div');
    frow.className = 'sheet-font';
    const fval = document.createElement('span');
    fval.className = 'sheet-font-val';
    fval.textContent = staged.font + '%';
    const range = document.createElement('input');
    range.type = 'range';
    range.min = '85';
    range.max = '130';
    range.step = '5';
    range.value = String(staged.font);
    range.setAttribute('aria-label', 'Font size');
    range.addEventListener('input', () => {
      staged.font = parseInt(range.value, 10);
      fval.textContent = staged.font + '%';
    });
    frow.appendChild(fval);
    frow.appendChild(range);
    fsec.appendChild(frow);
    body.appendChild(fsec);
    sheet.appendChild(body);

    const foot = document.createElement('div');
    foot.className = 'sheet-foot';
    const save = document.createElement('button');
    save.className = 'btn-save';
    save.textContent = T('Save');
    save.addEventListener('click', () => {
      const before = cur();
      localStorage.setItem('ux-theme', staged.theme);
      localStorage.setItem('ux-lang', staged.lang);
      localStorage.setItem('ux-font', String(staged.font));
      const root = document.documentElement;
      root.classList.remove('light', 'dark', 'beige', 'blue');
      if (staged.theme !== 'light') root.classList.add(staged.theme);
      applyFont(staged.font);
      close();
      if (staged.lang !== before.lang) location.href = window.uxLangUrl ? window.uxLangUrl(staged.lang) : location.href;
    });
    const cancel = document.createElement('button');
    cancel.className = 'btn-cancel';
    cancel.textContent = T('Cancel');
    cancel.addEventListener('click', close);
    foot.appendChild(save);
    foot.appendChild(cancel);
    sheet.appendChild(foot);
  };

  function open() {
    staged = cur();
    render();
    const nav = document.querySelector('.topnav');
    sheet.style.top = (nav ? Math.round(nav.getBoundingClientRect().bottom) : 0) + 'px';
    sheet.classList.add('open');
    const f = sheet.querySelector('.sheet-opt');
    if (f) f.focus();
    btn.setAttribute('aria-expanded', 'true');
  }
  function close() {
    const had = sheet.contains(document.activeElement);
    sheet.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
    if (had) btn.focus();
  }
  btn.addEventListener('click', e => {
    e.stopPropagation();
    sheet.classList.contains('open') ? close() : open();
  });
})();

// ---- Help panel (Help / Keyboard shortcuts), to the right of Settings ----
// Modeled on the help sheet at ux-icons.com: same slide-down chrome as
// Settings, prose topics in a grid, and a Keys/Action table generated from
// SHORTCUTS so the sheet and the key handler can never disagree.
(() => {
  const topnav = document.querySelector('.topnav');
  if (!topnav) return;
  const wrap = document.createElement('div');
  wrap.className = 'settings-wrap help-wrap';
  const btn = document.createElement('button');
  btn.className = 'settings-btn help-btn';
  btn.type = 'button';
  btn.setAttribute('aria-label', 'Help');
  btn.title = 'Help';
  btn.setAttribute('aria-expanded', 'false');
  btn.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/></svg>';
  wrap.appendChild(btn);
  topnav.appendChild(wrap);

  const HELP = [
    ['Browsing', 'The home page lists every guideline two ways: Page Type groups them by the screen you are designing, Task Type by what you are trying to do. The menu (☰) offers the same two views on every page. Your choice is remembered.'],
    ['Searching', 'Search matches page titles, the cards on each page, people, and glossary terms as you type. Pick a result to open it, or press Enter to open the first match.'],
    ['Reference pages', 'Each page opens with the origin of the idea and the law stated plainly, followed by cards showing how to apply it, a section on AI interfaces, and further reading. Chips on a card link to the most relevant neighboring page.'],
    ['Copying illustrations', 'Hover any illustration for a copy button that places it on your clipboard as an SVG, named after its card, ready for Figma or a document.'],
    ['Bookmarks', 'The bookmark button beside a page title keeps the page in this browser only. Open your list from the bookmark icon in the top bar, where you can revisit or remove pages.'],
    ['Settings', 'Choose a theme, language, and font size. Changes apply when you save; a new language opens the same page at its translated address.']
  ];
  const isByYear = !!document.querySelector('.yr-ctl');
  const clickIf = sel => { const el = document.querySelector(sel); if (el) el.click(); };
  const SHORTCUTS = [
    { keys: ['/'], label: 'Focus search', run: () => { const s = document.querySelector('.search-input'); if (s) { closeAll(); s.focus(); s.select(); } } },
    { keys: ['?'], label: 'Show keyboard shortcuts', run: () => (isOpen() ? close() : open('keys')) },
    { keys: ['m'], label: 'Open or close the menu', run: () => clickIf('.hamburger') },
    { keys: ['b'], label: 'Open or close bookmarks', run: () => clickIf('.bm-nav-btn') },
    { keys: ['s'], label: 'Open or close settings', run: () => clickIf('.settings-wrap:not(.help-wrap) .settings-btn:not(.bm-nav-btn)') },
    { keys: ['g', 'h'], label: 'Go to the home page', run: () => { location.href = (window.uxLocalHref ? window.uxLocalHref('index.html') : 'index.html'); } },
    { keys: ['g', 'p'], label: 'Go to People', run: () => { location.href = (window.uxLocalHref ? window.uxLocalHref('people.html') : 'people.html'); } },
    { keys: ['g', 'y'], label: 'Go to By Year', run: () => { location.href = (window.uxLocalHref ? window.uxLocalHref('by-year.html') : 'by-year.html'); } },
    { keys: ['→'], label: 'Next page', run: null },
    { keys: ['←'], label: 'Previous page', run: null },
    { keys: ['e'], label: 'Expand all sections', page: true, run: () => clickIf('.yr-ctl[data-act="expand"]') },
    { keys: ['c'], label: 'Collapse all sections', page: true, run: () => clickIf('.yr-ctl[data-act="collapse"]') },
    { keys: ['Esc'], label: 'Close menus, panels, and search', run: null }
  ];

  const sheet = document.createElement('div');
  sheet.className = 'settings-sheet help-sheet';
  sheet.setAttribute('role', 'dialog');
  sheet.setAttribute('aria-label', 'Help');
  const head = document.createElement('div');
  head.className = 'sheet-head';
  const title = document.createElement('h2');
  title.className = 'sheet-title';
  title.textContent = 'Help';
  const x = document.createElement('button');
  x.className = 'sheet-close';
  x.type = 'button';
  x.setAttribute('aria-label', 'Close help');
  x.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>';
  head.appendChild(title); head.appendChild(x); sheet.appendChild(head);
  const tabs = document.createElement('div');
  tabs.className = 'sheet-tabs';
  tabs.setAttribute('role', 'tablist');
  [['help', 'Help'], ['keys', 'Keyboard shortcuts']].forEach(([v, name]) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'sheet-tab'; b.setAttribute('role', 'tab'); b.dataset.view = v; b.textContent = name;
    // a tab has to name the panel it controls, and the panel has to name it back
    b.id = 'help-tab-' + v;
    b.setAttribute('aria-controls', 'help-panel-' + v);
    tabs.appendChild(b);
  });
  sheet.appendChild(tabs);
  const helpPanel = document.createElement('div');
  helpPanel.className = 'help-panel'; helpPanel.dataset.view = 'help'; helpPanel.setAttribute('role', 'tabpanel');
  helpPanel.id = 'help-panel-help'; helpPanel.setAttribute('aria-labelledby', 'help-tab-help');
  const grid = document.createElement('div'); grid.className = 'help-grid';
  HELP.forEach(([h, p]) => {
    const item = document.createElement('div'); item.className = 'help-item';
    const h3 = document.createElement('h3'); h3.textContent = h;
    const para = document.createElement('p'); para.textContent = p;
    item.appendChild(h3); item.appendChild(para); grid.appendChild(item);
  });
  helpPanel.appendChild(grid);
  const keysPanel = document.createElement('div');
  keysPanel.className = 'help-panel'; keysPanel.dataset.view = 'keys'; keysPanel.setAttribute('role', 'tabpanel'); keysPanel.hidden = true;
  keysPanel.id = 'help-panel-keys'; keysPanel.setAttribute('aria-labelledby', 'help-tab-keys');
  const table = document.createElement('table'); table.className = 'keys-table';
  const thead = document.createElement('thead'); thead.innerHTML = '<tr><th class="keys-col">Keys</th><th class="keys-col">Action</th></tr>';
  const tbody = document.createElement('tbody');
  SHORTCUTS.forEach(sc => {
    const tr = document.createElement('tr');
    const td1 = document.createElement('td');
    sc.keys.forEach((k, i) => {
      if (i) { const then = document.createElement('span'); then.className = 'keys-then'; then.textContent = 'then'; td1.appendChild(then); }
      const kbd = document.createElement('kbd'); kbd.className = 'key'; kbd.textContent = k; td1.appendChild(kbd);
    });
    const td2 = document.createElement('td');
    const lab = document.createElement('span'); lab.className = 'keys-action'; lab.textContent = sc.label; td2.appendChild(lab);
    if (sc.page) { const only = document.createElement('span'); only.className = 'keys-then keys-page'; only.textContent = '(By Year page)'; td2.appendChild(only); }
    tr.appendChild(td1); tr.appendChild(td2); tbody.appendChild(tr);
  });
  table.appendChild(thead); table.appendChild(tbody); keysPanel.appendChild(table);
  sheet.appendChild(helpPanel); sheet.appendChild(keysPanel);
  document.body.appendChild(sheet);

  const setView = v => {
    tabs.querySelectorAll('.sheet-tab').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === v)));
    helpPanel.hidden = v !== 'help'; keysPanel.hidden = v !== 'keys';
  };
  tabs.addEventListener('click', e => { const b = e.target.closest('.sheet-tab'); if (b) setView(b.dataset.view); });
  setView('help');

  const isOpen = () => sheet.classList.contains('open');
  function closeAll() {
    const gear = document.querySelector('.settings-wrap:not(.help-wrap) .settings-btn:not(.bm-nav-btn)[aria-expanded="true"]');
    if (gear) gear.click();
    const menu = document.querySelector('.hamburger[aria-expanded="true"]');
    if (menu) menu.click();
    const bm = document.querySelector('.bm-nav-btn[aria-expanded="true"]');
    if (bm) bm.click();
  }
  function open(view) {
    closeAll();
    if (view) setView(view);
    const nav = document.querySelector('.topnav');
    sheet.style.top = (nav ? Math.round(nav.getBoundingClientRect().bottom) : 0) + 'px';
    sheet.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
    x.focus();
  }
  function close() {
    const had = sheet.contains(document.activeElement);
    sheet.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
    if (had) btn.focus();
  }
  btn.addEventListener('click', e => { e.stopPropagation(); isOpen() ? close() : open(); });
  x.addEventListener('click', close);

  // Single keys and two-key chords (g then h), ignored while typing.
  let pending = null, pendingTimer = 0;
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') { if (isOpen()) close(); return; }
    const tgt = e.target;
    if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.isContentEditable)) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const k = e.key;
    if (pending) {
      const chord = SHORTCUTS.find(sc => sc.keys.length === 2 && sc.keys[0] === pending && sc.keys[1] === k);
      pending = null; clearTimeout(pendingTimer);
      if (chord && chord.run) { e.preventDefault(); chord.run(); return; }
    }
    if (SHORTCUTS.some(sc => sc.keys.length === 2 && sc.keys[0] === k)) {
      pending = k; pendingTimer = setTimeout(() => { pending = null; }, 1200); return;
    }
    const sc = SHORTCUTS.find(s => s.keys.length === 1 && s.keys[0] === k && s.run && (!s.page || isByYear));
    if (sc) { e.preventDefault(); sc.run(); }
  });
  setTimeout(() => {
    if (!window.uxT) return;
    const l = window.uxT('Help');
    if (l) { btn.setAttribute('aria-label', l); btn.title = l; sheet.setAttribute('aria-label', l); }
  }, 1600);
})();

// Language URLs: /fr/... path prefixes (hreflang alternates, rewritten by
// .htaccess to the same page shell) and legacy ?lang= parameters both select
// and persist a language. The path prefix is the canonical form.
(() => {
  try {
    const pm = location.pathname.match(/^\/(fr|de|es|ja|zh)(?:\/|$)/);
    const qm = location.search.match(/[?&]lang=([a-z]{2})\b/);
    const code = pm ? pm[1] : (qm && ['en', 'es', 'de', 'fr', 'zh', 'ja'].includes(qm[1]) ? qm[1] : null);
    if (code) localStorage.setItem('ux-lang', code);
    // repair any corrupted stored language (e.g. the literal string "undefined")
    if (!['en', 'es', 'de', 'fr', 'zh', 'ja'].includes(localStorage.getItem('ux-lang') || 'en')) localStorage.setItem('ux-lang', 'en');
    if (pm) {
      const page = location.pathname.replace(/^\/(fr|de|es|ja|zh)\/?/, '');
      const self = 'https://www.ux-guidelines.com/' + pm[1] + '/' + page;
      const c = document.querySelector('link[rel="canonical"]');
      if (c) c.href = self;
      const og = document.querySelector('meta[property="og:url"]');
      if (og) og.content = self;
      document.querySelectorAll('meta[property="og:image"], meta[name="twitter:image"]').forEach(el => {
        el.content = el.content.replace('/og/en/', '/og/' + pm[1] + '/');
      });
    }
  } catch (e) {}
  // Build the URL for a language on the current page (used by every switcher).
  // On a language URL, every internal link keeps the language prefix so navigation
  // never drops back to English. Links added later (search results, bookmarks,
  // home view clones) are caught by the observer.
  (() => {
    const m = location.pathname.match(/^\/(fr|de|es|ja|zh)(?:\/|$)/);
    if (!m) { window.uxLocalHref = h => h; return; }
    const lang = m[1];
    const S = (window.UX_SLUGS && window.UX_SLUGS[lang]) || {};
    const local = href => {
      if (!href || /^(https?:|mailto:|tel:|#|\/|\.\.)/.test(href)) return href;
      const mm = href.match(/^([a-z0-9-]+)\.html((?:\?[^#]*)?(?:#.*)?)$/);
      if (!mm || /^(roadmap|design-system)$/.test(mm[1])) return href;
      return '/' + lang + '/' + (S[mm[1]] || mm[1]) + '.html' + mm[2];
    };
    window.uxLocalHref = local;
    const fixOne = a => {
      if (a.dataset.langFixed) return;
      const h = a.getAttribute('href'), n = local(h);
      if (n !== h) a.setAttribute('href', n);
      a.dataset.langFixed = '1';
    };
    const fix = root => { if (root.tagName === 'A') fixOne(root); root.querySelectorAll && root.querySelectorAll('a[href]').forEach(fixOne); };
    fix(document.documentElement);
    new MutationObserver(muts => muts.forEach(mu => mu.addedNodes.forEach(nd => { if (nd.nodeType === 1) fix(nd); })))
      .observe(document.documentElement, { childList: true, subtree: true });
  })();
  window.uxLangUrl = code => {
    // Work from the file name, not data-page: the two differ on most pages
    // (power-law-of-practice.html is data-page="power-law"), and the slug map
    // and the URL are both keyed by the file name.
    const hash = location.hash || '';
    let en = (location.pathname.split('/').pop() || 'index.html').replace(/\.html$/, '') || 'index';
    const here = location.pathname.match(/^\/(fr|de|es|ja|zh)(?:\/|$)/);
    // /fr with no trailing slash leaves the language code as the last segment,
    // which would resolve to a page called "fr". That path is the home page.
    if (here && en === here[1]) en = 'index';
    if (here) {   // already on a language path: map the localized slug back to English
      const M = (window.UX_SLUGS && window.UX_SLUGS[here[1]]) || {};
      for (const k in M) { if (M[k] === en) { en = k; break; } }
    }
    if (code === 'en') return (en === 'index' ? '/index.html' : '/' + en + '.html') + hash;
    const S = (window.UX_SLUGS && window.UX_SLUGS[code]) || {};
    return (en === 'index' ? '/' + code + '/' : '/' + code + '/' + (S[en] || en) + '.html') + hash;
  };
  const lang = localStorage.getItem('ux-lang');
  if (!lang || lang === 'en') return;
  const s = document.createElement('script');
  s.src = 'i18n.js?v=65';
  document.head.appendChild(s);
})();

// Compact page title under the topnav, at every width. Once the h1 scrolls out
// of the scroller there is nothing left on screen naming the page, so a bar the
// height of the nav takes over, carrying the bookmark and share buttons with it.
// Reference pages only: the home page and the index pages would just repeat the
// brand already in the nav.
(() => {
  const h1 = document.querySelector('header h1');
  if (!h1 || !document.querySelector('.law-feature')) return;
  const nav = document.querySelector('.topnav');
  const bar = document.createElement('div');
  bar.className = 'sticky-title';
  const text = document.createElement('span');
  text.className = 'st-text';
  text.setAttribute('aria-hidden', 'true');   // the real h1 is still in the page
  bar.appendChild(text);
  // Read the live h1 so a translation applied after load carries through.
  const sync = () => { text.textContent = h1.textContent.trim(); };
  sync();
  new MutationObserver(sync).observe(h1, { childList: true, subtree: true, characterData: true });
  const place = () => {
    if (nav) bar.style.top = nav.offsetHeight + 'px';
    // A height measured for the phone sheet must not survive into the wider
    // layout, where it would clip the dropdown instead of sizing a sheet.
    const m = bar.querySelector('.share-menu');
    if (m) m.style.maxHeight = '';
  };
  place();
  window.addEventListener('resize', place);
  document.body.appendChild(bar);

  // The bookmark and share buttons are built later, by the title-actions module.
  // Move the real element rather than cloning it: the handlers are closures over
  // those nodes, and the share menu is positioned against its own wrapper, so a
  // copy would be inert and would open its menu in the wrong place.
  let shown = false;
  const phone = () => window.matchMedia('(max-width: 600px)').matches;
  const menuOf = () => bar.querySelector('.share-menu');
  const toggle = on => {
    if (on === shown) return;
    shown = on;
    const actions = document.querySelector('.title-actions');
    const row = document.querySelector('.title-row');
    const m = menuOf();
    if (m) m.style.maxHeight = '';   // never carry the sheet height out of the bar
    if (actions && row) (on ? bar : row).appendChild(actions);
    bar.classList.toggle('show', on);
  };
  // On a phone the share menu is a sheet that rolls down out of the bar. Measure
  // it as it opens so the animation eases to its real height rather than to a
  // guessed maximum, and clear the value on close so it can collapse again.
  new MutationObserver(() => {
    const m = menuOf();
    if (!m || !phone()) return;
    m.style.maxHeight = m.classList.contains('open') ? m.scrollHeight + 'px' : '';
  }).observe(bar, { attributes: true, attributeFilter: ['class'], subtree: true });
  new IntersectionObserver(
    ([e]) => toggle(!e.isIntersecting && e.boundingClientRect.top < 0),
    { root: window.uxScroller || null, threshold: 0 }
  ).observe(h1);
})();

// A closed panel is moved out of sight with a transform, which hides it from the
// eye but not from the Tab key: the shut hamburger menu alone holds ~59 stops
// that a keyboard user walks through before reaching the page. `inert` takes a
// subtree out of focus order, hit-testing and the accessibility tree at once, so
// the panels track it against their own open class instead of every open and
// close function having to remember.
(() => {
  const SEL = '.menu-panel, .settings-sheet, .bm-sheet, .share-menu';
  const sync = el => { el.inert = !el.classList.contains('open'); };
  const watch = el => {
    sync(el);
    new MutationObserver(() => sync(el)).observe(el, { attributes: true, attributeFilter: ['class'] });
  };
  document.querySelectorAll(SEL).forEach(watch);
  // several of these panels are built by later modules, so pick them up as they land
  new MutationObserver(muts => muts.forEach(mu => mu.addedNodes.forEach(n => {
    if (n.nodeType !== 1) return;
    if (n.matches && n.matches(SEL)) watch(n);
    if (n.querySelectorAll) n.querySelectorAll(SEL).forEach(watch);
  }))).observe(document.body, { childList: true, subtree: true });
})();

// Letter navigation sticks just below the topnav; bordered while stuck
(() => {
  const an = document.querySelector('.alpha-nav');
  const nav = document.querySelector('.topnav');
  if (!an || !nav) return;
  an.style.top = (window.uxScroller ? 0 : nav.offsetHeight) + 'px';
  let ticking = false;
  const check = () => {
    ticking = false;
    const stuck = an.getBoundingClientRect().top <= nav.getBoundingClientRect().bottom + 1;
    an.classList.toggle('stuck', stuck);
  };
  (window.uxScroller || window).addEventListener('scroll', () => {
    if (!ticking) { ticking = true; requestAnimationFrame(check); }
  }, { passive: true });
  check();
})();

